1	/** @jsxImportSource @opentui/solid */
2	
3	import { For, Show, createMemo, createSignal, onCleanup, onMount } from 'solid-js';
4	import { useKeyboard, useRenderer, useTerminalDimensions } from '@opentui/solid';
5	import type { KeyEvent } from '@opentui/core';
6	import type { AppPaths } from './paths.ts';
7	import { discoverAll } from './discovery.ts';
8	import {
9	  deleteSkills,
10	  findForkCollision,
11	  findMoveCollisions,
12	  forkSkill,
13	  moveSkills,
14	  normalizeForkName,
15	} from './operations.ts';
16	import {
17	  findInstallCollision,
18	  installSearchResult,
19	  loadInstallPreview,
20	  SEARCH_PAGE_SIZE,
21	  searchNeedsMore,
22	  searchSkills,
23	  type InstallPreview,
24	  type SearchSkill,
25	} from './install.ts';
26	import { checkForUpdates, updateSkills } from './updates.ts';
27	import type { AppSnapshot, OperationResult, ScopeId, SkillRecord, UpdateState } from './types.ts';
28	import { COLORS, shortenHome } from './ui/common.tsx';
29	import { SkillPane } from './ui/panes.tsx';
30	import { StatusBar } from './ui/statusbar.tsx';
31	import {
32	  ConfirmView,
33	  ForkView,
34	  ModalFrame,
35	  SearchQueryView,
36	  SearchResultsView,
37	  searchResultsCapacity,
38	  type ForkModal,
39	  type Modal,
40	  type SearchModal,
41	} from './ui/modals.tsx';
42	
43	function allSkills(snapshot: AppSnapshot | null): SkillRecord[] {
44	  return snapshot ? [...snapshot.project.skills, ...snapshot.global.skills] : [];
45	}
46	
47	function isEnter(key: KeyEvent): boolean {
48	  return key.name === 'return' || key.name === 'enter';
49	}
50	
51	function typedCharacter(key: KeyEvent): string | null {
52	  if (key.ctrl || key.meta || key.option) return null;
53	  return key.raw.length === 1 && key.raw >= ' ' && key.raw !== '\x7f' ? key.raw : null;
54	}
55	
56	function operationStatus(result: OperationResult): string {
57	  if (result.errors.length === 0) return result.message;
58	  return `${result.message}. ${result.errors[0]}`;
59	}
60	
61	export function App(props: { paths: AppPaths }) {
62	  const renderer = useRenderer();
63	  const dimensions = useTerminalDimensions();
64	  const [snapshot, setSnapshot] = createSignal<AppSnapshot | null>(null);
65	  const projectEnabled = () => props.paths.projectEnabled;
66	  const visibleScopes = (): ScopeId[] =>
67	    projectEnabled() ? (['project', 'global'] as ScopeId[]) : (['global'] as ScopeId[]);
68	  const [activeScope, setActiveScope] = createSignal<ScopeId>(
69	    props.paths.projectEnabled ? 'project' : 'global'
70	  );
71	  const [cursor, setCursor] = createSignal<Record<ScopeId, number>>({ project: 0, global: 0 });
72	  const [selected, setSelected] = createSignal(new Set<string>());
73	  const [updates, setUpdates] = createSignal<Record<string, UpdateState>>({});
74	  const [status, setStatus] = createSignal('Loading skills');
75	  const [statusTone, setStatusTone] = createSignal<'idle' | 'alert'>('idle');
76	  const [busy, setBusy] = createSignal(false);
77	  const [loading, setLoading] = createSignal(false);
78	  const [modal, setModal] = createSignal<Modal | null>(null);
79	  const installPreviewCache = new Map<string, InstallPreview>();
80	  let disposed = false;
81	  let checkGeneration = 0;
82	  let previewGeneration = 0;
83	  let searchGeneration = 0;
84	
85	  function announce(message: string, alert = false): void {
86	    setStatus(message);
87	    setStatusTone(alert ? 'alert' : 'idle');
88	  }
89	
90	  const scopeSnapshot = (scope: ScopeId) => snapshot()?.[scope];
91	  const scopeSkills = (scope: ScopeId) => scopeSnapshot(scope)?.skills || [];
92	  const currentSkill = createMemo(() => {
93	    const list = scopeSkills(activeScope());
94	    return list[cursor()[activeScope()]] || null;
95	  });
96	  const selectedSkills = createMemo(() => {
97	    const ids = selected();
98	    return allSkills(snapshot()).filter((skill) => ids.has(skill.id));
99	  });
100	
101	  function clampCursors(data: AppSnapshot): void {
102	    setCursor((previous) => ({
103	      project: Math.max(0, Math.min(previous.project, data.project.skills.length - 1)),
104	      global: Math.max(0, Math.min(previous.global, data.global.skills.length - 1)),
105	    }));
106	  }
107	
108	  async function runBackgroundCheck(data: AppSnapshot): Promise<void> {
109	    const generation = ++checkGeneration;
110	    const tracked = allSkills(data).filter((skill) => skill.tracked);
111	    const initial: Record<string, UpdateState> = {};
112	    for (const skill of tracked) initial[skill.id] = 'checking';
113	    setUpdates(initial);
114	    if (tracked.length === 0) return;
115	
116	    const result = await checkForUpdates(tracked);
117	    if (disposed || generation !== checkGeneration) return;
118	    setUpdates(result.states);
119	    const available = Object.values(result.states).filter((state) => state === 'available').length;
120	    if (available > 0) {
121	      announce(`${available} update${available === 1 ? '' : 's'} available`, true);
122	    } else if (result.errors.length > 0) {
123	      announce('Local skills ready. Some updates could not be checked', true);
124	    }
125	  }
126	
127	  async function refresh(check = true): Promise<void> {
128	    setLoading(true);
129	    try {
130	      const data = await discoverAll(props.paths);
131	      if (disposed) return;
132	      setSnapshot(data);
133	      clampCursors(data);
134	      const existing = new Set(allSkills(data).map((skill) => skill.id));
135	      setSelected((previous) => new Set([...previous].filter((id) => existing.has(id))));
136	      announce(
137	        projectEnabled()
138	          ? `${data.project.skills.length} project, ${data.global.skills.length} global`
139	          : `${data.global.skills.length} global`
140	      );
141	      if (check) void runBackgroundCheck(data);
142	    } catch (error) {
143	      announce((error as Error).message, true);
144	    } finally {
145	      setLoading(false);
146	    }
147	  }
148	
149	  async function runOperation(
150	    label: string,
151	    action: () => Promise<OperationResult>
152	  ): Promise<void> {
153	    setModal(null);
154	    setBusy(true);
155	    announce(label);
156	    try {
157	      const result = await action();
158	      setSelected(new Set<string>());
159	      await refresh(true);
160	      announce(operationStatus(result), result.errors.length > 0);
161	    } catch (error) {
162	      announce((error as Error).message, true);
163	    } finally {
164	      setBusy(false);
165	    }
166	  }
167	
168	  function actionTargets(scope?: ScopeId): SkillRecord[] {
169	    const chosen = selectedSkills().filter((skill) => !scope || skill.scope === scope);
170	    if (chosen.length > 0) return chosen;
171	    const current = currentSkill();
172	    return current && (!scope || current.scope === scope) ? [current] : [];
173	  }
174	
175	  function openDelete(): void {
176	    const targets = actionTargets();
177	    if (targets.length === 0) {
178	      announce('No skill to delete', true);
179	      return;
180	    }
181	    setModal({
182	      type: 'confirm',
183	      title: `Delete ${targets.length} skill${targets.length === 1 ? '' : 's'}?`,
184	      lines: ['These folders will be removed:', '', ...targets.map((skill) => skill.path)],
185	      offset: 0,
186	      action: () => runOperation('Deleting skills', () => deleteSkills(props.paths, targets)),
187	    });
188	  }
189	
190	  async function startMove(): Promise<void> {
191	    if (!projectEnabled()) {
192	      announce('Project scope is unavailable from the home directory', true);
193	      return;
194	    }
195	    const scope = activeScope();
196	    const targets = actionTargets(scope);
197	    if (targets.length === 0) {
198	      announce('No skill to move', true);
199	      return;
200	    }
201	    setBusy(true);
202	    try {
203	      const collisions = await findMoveCollisions(props.paths, targets);
204	      if (collisions.length > 0) {
205	        setModal({
206	          type: 'confirm',
207	          title: `Overwrite ${collisions.length} destination${collisions.length === 1 ? '' : 's'}?`,
208	          lines: [
209	            'Existing folders and their lock entries will be replaced:',
210	            '',
211	            ...collisions.flatMap((collision) => [
212	              collision.destination,
213	              `from ${collision.source}`,
214	            ]),
215	          ],
216	          offset: 0,
217	          action: () => runOperation('Moving skills', () => moveSkills(props.paths, targets, true)),
218	        });
219	      } else {
220	        await runOperation('Moving skills', () => moveSkills(props.paths, targets));
221	      }
222	    } finally {
223	      setBusy(false);
224	    }
225	  }
226	
227	  function openFork(): void {
228	    const selectedNow = selectedSkills();
229	    if (selectedNow.length > 1) {
230	      announce('Fork accepts one skill', true);
231	      return;
232	    }
233	    const skill = selectedNow[0] || currentSkill();
234	    if (!skill) {
235	      announce('No skill to fork', true);
236	      return;
237	    }
238	    setModal({ type: 'fork', skill, value: `${skill.folderName}-fork` });
239	  }
240	
241	  async function submitFork(forkModal: ForkModal): Promise<void> {
242	    const name = normalizeForkName(forkModal.value);
243	    if (!name) {
244	      announce('Fork name is empty', true);
245	      return;
246	    }
247	    setBusy(true);
248	    try {
249	      const collision = await findForkCollision(props.paths, forkModal.skill, name);
250	      if (collision) {
251	        setModal({
252	          type: 'confirm',
253	          title: `Overwrite ${name}?`,
254	          lines: [
255	            'The existing fork destination and its lock entry will be replaced:',
256	            '',
257	            collision.destination,
258	          ],
259	          offset: 0,
260	          action: () =>
261	            runOperation('Forking skill', () =>
262	              forkSkill(props.paths, forkModal.skill, name, true)
263	            ),
264	        });
265	      } else {
266	        await runOperation('Forking skill', () => forkSkill(props.paths, forkModal.skill, name));
267	      }
268	    } finally {
269	      setBusy(false);
270	    }
271	  }
272	
273	  function searchStatus(count: number, hasMore: boolean, loadingMore = false): string {
274	    if (count === 0) return 'No results, or skills.sh could not be reached';
275	    const noun = `${count} result${count === 1 ? '' : 's'}`;
276	    if (loadingMore) return `${noun} · loading more`;
277	    return hasMore ? `${noun} · more available` : noun;
278	  }
279	
280	  function openSearch(scope: ScopeId): void {
281	    previewGeneration++;
282	    searchGeneration++;
283	    setModal({
284	      type: 'search',
285	      scope,
286	      phase: 'query',
287	      query: '',
288	      results: [],
289	      index: 0,
290	      loading: false,
291	      loadingMore: false,
292	      hasMore: false,
293	      message: 'Type at least two characters, then press Enter',
294	      preview: '',
295	      previewFile: '',
296	      previewState: 'idle',
297	      previewOffset: 0,
298	    });
299	  }
300	
301	  function previewKey(result: SearchSkill): string {
302	    return `${result.source}\0${result.name}`;
303	  }
304	
305	  async function selectSearchResult(searchModal: SearchModal, index: number): Promise<void> {
306	    const result = searchModal.results[index];
307	    if (!result) return;
308	    if (index === searchModal.index && searchModal.previewState !== 'idle') return;
309	
310	    const generation = ++previewGeneration;
311	    const key = previewKey(result);
312	    const cached = installPreviewCache.get(key);
313	    const next: SearchModal = {
314	      ...searchModal,
315	      index,
316	      preview: cached?.contents || '',
317	      previewFile: cached?.fileName || '',
318	      previewState: cached ? 'ready' : 'loading',
319	      previewOffset: 0,
320	    };
321	    setModal(next);
322	    if (cached) return;
323	
324	    try {
325	      const preview = await loadInstallPreview(result);
326	      installPreviewCache.set(key, preview);
327	      const current = modal();
328	      if (
329	        disposed ||
330	        generation !== previewGeneration ||
331	        !current ||
332	        current.type !== 'search' ||
333	        current.phase !== 'results' ||
334	        previewKey(current.results[current.index]!) !== key
335	      ) {
336	        return;
337	      }
338	      setModal({
339	        ...current,
340	        preview: preview.contents,
341	        previewFile: preview.fileName,
342	        previewState: 'ready',
343	        previewOffset: 0,
344	      });
345	    } catch (error) {
346	      const current = modal();
347	      if (
348	        disposed ||
349	        generation !== previewGeneration ||
350	        !current ||
351	        current.type !== 'search' ||
352	        current.phase !== 'results' ||
353	        previewKey(current.results[current.index]!) !== key
354	      ) {
355	        return;
356	      }
357	      setModal({
358	        ...current,
359	        preview: (error as Error).message,
360	        previewFile: '',
361	        previewState: 'error',
362	        previewOffset: 0,
363	      });
364	    }
365	  }
366	
367	  async function submitSearch(searchModal: SearchModal): Promise<void> {
368	    if (searchModal.query.trim().length < 2) {
369	      setModal({ ...searchModal, message: 'Search needs at least two characters' });
370	      return;
371	    }
372	    const generation = ++searchGeneration;
373	    setModal({
374	      ...searchModal,
375	      loading: true,
376	      loadingMore: false,
377	      hasMore: false,
378	      message: 'Searching skills.sh',
379	    });
380	    const page = await searchSkills(searchModal.query);
381	    const current = modal();
382	    if (disposed || generation !== searchGeneration || !current || current.type !== 'search') {
383	      return;
384	    }
385	    const next: SearchModal = {
386	      ...current,
387	      phase: 'results',
388	      results: page.skills,
389	      index: 0,
390	      loading: false,
391	      loadingMore: false,
392	      hasMore: page.hasMore,
393	      message: searchStatus(page.skills.length, page.hasMore),
394	      preview: '',
395	      previewFile: '',
396	      previewState: 'idle',
397	      previewOffset: 0,
398	    };
399	    setModal(next);
400	    if (page.hasMore && shouldPrefetchSearch(next, 0)) {
401	      void loadMoreResults(next, 0);
402	    } else if (page.skills.length > 0) {
403	      void selectSearchResult(next, 0);
404	    }
405	  }
406	
407	  async function loadMoreResults(searchModal: SearchModal, selectIndex?: number): Promise<void> {
408	    if (!searchModal.hasMore || searchModal.loading || searchModal.loadingMore) return;
409	    const generation = searchGeneration;
410	    const offset = searchModal.results.length;
411	    const latest = modal();
412	    const base = latest && latest.type === 'search' ? latest : searchModal;
413	    setModal({
414	      ...base,
415	      loadingMore: true,
416	      message: searchStatus(base.results.length, true, true),
417	    });
418	    const page = await searchSkills(searchModal.query, offset);
419	    const current = modal();
420	    if (
421	      disposed ||
422	      generation !== searchGeneration ||
423	      !current ||
424	      current.type !== 'search' ||
425	      current.phase !== 'results'
426	    ) {
427	      return;
428	    }
429	    const seen = new Set(
430	      current.results.map((result) => result.slug || `${result.source}\0${result.name}`)
431	    );
432	    const extra = page.skills.filter(
433	      (result) => !seen.has(result.slug || `${result.source}\0${result.name}`)
434	    );
435	    const results = [...current.results, ...extra];
436	    const hasMore = extra.length > 0 && page.hasMore;
437	    const nextIndex =
438	      selectIndex === undefined
439	        ? Math.min(current.index, Math.max(0, results.length - 1))
440	        : Math.min(Math.max(selectIndex, 0), Math.max(0, results.length - 1));
441	    const next: SearchModal = {
442	      ...current,
443	      results,
444	      loadingMore: false,
445	      hasMore,
446	      message: searchStatus(results.length, hasMore),
447	    };
448	    setModal(next);
449	    if (hasMore && shouldPrefetchSearch(next, nextIndex)) {
450	      void loadMoreResults(next, nextIndex);
451	    } else if (results[nextIndex]) {
452	      void selectSearchResult(next, nextIndex);
453	    }
454	  }
455	
456	  function visibleSearchRows(): number {
457	    return searchResultsCapacity(dimensions().width, dimensions().height);
458	  }
459	
460	  function shouldPrefetchSearch(searchModal: SearchModal, index: number): boolean {
461	    if (!searchModal.hasMore || searchModal.loading || searchModal.loadingMore) return false;
462	    return (
463	      searchNeedsMore(index, searchModal.results.length) ||
464	      searchModal.results.length < visibleSearchRows()
465	    );
466	  }
467	
468	  function moveSearchCursor(searchModal: SearchModal, index: number): void {
469	    const next = Math.max(0, Math.min(index, searchModal.results.length - 1));
470	    void selectSearchResult(searchModal, next);
471	    if (shouldPrefetchSearch(searchModal, next)) void loadMoreResults(searchModal);
472	  }
473	
474	  function pageSearchResults(searchModal: SearchModal, direction: 1 | -1): void {
475	    const target = searchModal.index + direction * SEARCH_PAGE_SIZE;
476	    if (direction > 0 && target >= searchModal.results.length) {
477	      if (searchModal.hasMore) {
478	        void loadMoreResults(searchModal, target);
479	        return;
480	      }
481	      moveSearchCursor(searchModal, searchModal.results.length - 1);
482	      return;
483	    }
484	    moveSearchCursor(searchModal, target);
485	  }
486	
487	  async function installSelected(searchModal: SearchModal, scope: ScopeId): Promise<void> {
488	    const result = searchModal.results[searchModal.index];
489	    if (!result) {
490	      announce('No search result selected', true);
491	      return;
492	    }
493	    setBusy(true);
494	    try {
495	      const collision = await findInstallCollision(props.paths, result, scope);
496	      if (collision) {
497	        setModal({
498	          type: 'confirm',
499	          title: `Overwrite ${collision.skillName}?`,
500	          lines: [
501	            'This installed folder and its lock entry will be replaced:',
502	            '',
503	            collision.destination,
504	          ],
505	          offset: 0,
506	          action: () =>
507	            runOperation(`Installing ${result.name}`, () =>
508	              installSearchResult(props.paths, result, scope, true)
509	            ),
510	        });
511	      } else {
512	        await runOperation(`Installing ${result.name}`, () =>
513	          installSearchResult(props.paths, result, scope)
514	        );
515	      }
516	    } finally {
517	      setBusy(false);
518	    }
519	  }
520	
521	  function startUpdate(): void {
522	    const targets = actionTargets();
523	    const tracked = targets.filter((skill) => skill.tracked);
524	    if (tracked.length === 0) {
525	      announce('No tracked skill selected', true);
526	      return;
527	    }
528	    void runOperation('Updating skills. Local edits may be overwritten', () =>
529	      updateSkills(props.paths, targets)
530	    );
531	  }
532	
533	  function moveCursor(delta: number): void {
534	    const scope = activeScope();
535	    const length = scopeSkills(scope).length;
536	    if (length === 0) return;
537	    setCursor((current) => ({
538	      ...current,
539	      [scope]: Math.max(0, Math.min(current[scope] + delta, length - 1)),
540	    }));
541	  }
542	
543	  function returnToSearch(searchModal: SearchModal): void {
544	    previewGeneration++;
545	    searchGeneration++;
546	    setModal({
547	      ...searchModal,
548	      phase: 'query',
549	      results: [],
550	      index: 0,
551	      loadingMore: false,
552	      hasMore: false,
553	      preview: '',
554	      previewFile: '',
555	      previewState: 'idle',
556	      previewOffset: 0,
557	    });
558	  }
559	
560	  function handleModalKey(key: KeyEvent, activeModal: Modal): void {
561	    key.preventDefault();
562	    if (key.name === 'escape') {
563	      if (activeModal.type === 'search' && activeModal.phase === 'results') {
564	        returnToSearch(activeModal);
565	        return;
566	      }
567	      previewGeneration++;
568	      searchGeneration++;
569	      setModal(null);
570	      announce('Cancelled');
571	      return;
572	    }
573	
574	    if (activeModal.type === 'confirm') {
575	      if (key.name.toLowerCase() === 'y') void activeModal.action();
576	      if (key.name.toLowerCase() === 'n') {
577	        setModal(null);
578	        announce('Cancelled');
579	      }
580	      if (key.name === 'j' || key.name === 'down' || key.name === 'pagedown') {
581	        const step = key.name === 'pagedown' ? 8 : 1;
582	        setModal({
583	          ...activeModal,
584	          offset: Math.min(activeModal.offset + step, Math.max(0, activeModal.lines.length - 1)),
585	        });
586	      }
587	      if (key.name === 'k' || key.name === 'up' || key.name === 'pageup') {
588	        const step = key.name === 'pageup' ? 8 : 1;
589	        setModal({ ...activeModal, offset: Math.max(0, activeModal.offset - step) });
590	      }
591	      return;
592	    }
593	
594	    if (activeModal.type === 'fork') {
595	      if (isEnter(key)) return void submitFork(activeModal);
596	      if (key.name === 'backspace') {
597	        setModal({ ...activeModal, value: activeModal.value.slice(0, -1) });
598	        return;
599	      }
600	      const character = typedCharacter(key);
601	      if (character) setModal({ ...activeModal, value: activeModal.value + character });
602	      return;
603	    }
604	
605	    if (activeModal.phase === 'query') {
606	      if (isEnter(key)) return void submitSearch(activeModal);
607	      if (key.name === 'backspace') {
608	        setModal({ ...activeModal, query: activeModal.query.slice(0, -1) });
609	        return;
610	      }
611	      const character = typedCharacter(key);
612	      if (character) setModal({ ...activeModal, query: activeModal.query + character });
613	      return;
614	    }
615	
616	    if (key.name === 'backspace') {
617	      returnToSearch(activeModal);
618	    } else if (key.name === 'j' || key.name === 'down') {
619	      moveSearchCursor(activeModal, activeModal.index + 1);
620	    } else if (key.name === 'k' || key.name === 'up') {
621	      moveSearchCursor(activeModal, activeModal.index - 1);
622	    } else if (key.name.toLowerCase() === 'n') {
623	      pageSearchResults(activeModal, 1);
624	    } else if (key.name.toLowerCase() === 'p') {
625	      pageSearchResults(activeModal, -1);
626	    } else if (key.name === 'pagedown') {
627	      const max = Math.max(0, activeModal.preview.split(/\r?\n/).length - 1);
628	      setModal({
629	        ...activeModal,
630	        previewOffset: Math.min(max, activeModal.previewOffset + 10),
631	      });
632	    } else if (key.name === 'pageup') {
633	      setModal({ ...activeModal, previewOffset: Math.max(0, activeModal.previewOffset - 10) });
634	    } else if (isEnter(key)) {
635	      void installSelected(activeModal, activeModal.scope);
636	    } else if (key.name.toLowerCase() === 'i') {
637	      const scope = key.shift || !projectEnabled() ? 'global' : 'project';
638	      void installSelected(activeModal, scope);
639	    }
640	  }
641	
642	  useKeyboard((key) => {
643	    const activeModal = modal();
644	    if (activeModal) return handleModalKey(key, activeModal);
645	    if (busy()) return;
646	    const keyName = key.name.toLowerCase();
647	
648	    if ((key.ctrl && keyName === 'c') || keyName === 'q') return renderer.destroy();
649	    if (keyName === 'j' || keyName === 'down') return moveCursor(1);
650	    if (keyName === 'k' || keyName === 'up') return moveCursor(-1);
651	    if (keyName === 'h' || keyName === 'left') {
652	      if (projectEnabled()) setActiveScope('project');
653	      return;
654	    }
655	    if (keyName === 'l' || keyName === 'right') {
656	      setActiveScope('global');
657	      return;
658	    }
659	    if (keyName === 'x') {
660	      const skill = currentSkill();
661	      if (!skill) return;
662	      setSelected((previous) => {
663	        const next = new Set(previous);
664	        if (next.has(skill.id)) next.delete(skill.id);
665	        else next.add(skill.id);
666	        return next;
667	      });
668	      return;
669	    }
670	    if (keyName === 'd' && key.shift) return openDelete();
671	    if (keyName === 'm' && key.shift) return void startMove();
672	    if (keyName === 'f' && key.shift) return openFork();
673	    if (keyName === 'u' && key.shift) return startUpdate();
674	    if (keyName === 'i') {
675	      return openSearch(key.shift || !projectEnabled() ? 'global' : 'project');
676	    }
677	    if (keyName === 'r') return void refresh(true);
678	  });
679	
680	  onMount(() => void refresh(true));
681	  onCleanup(() => {
682	    disposed = true;
683	    checkGeneration++;
684	    previewGeneration++;
685	    searchGeneration++;
686	  });
687	
688	  const paneBudget = () => Math.max(3, dimensions().height - 10);
689	
690	  function paneRows(scope: ScopeId): SkillRecord[] {
691	    const list = scopeSkills(scope);
692	    const budget = paneBudget();
693	    const center = cursor()[scope];
694	    const start = Math.max(0, Math.min(center - Math.floor(budget / 2), list.length - budget));
695	    return list.slice(start, start + budget);
696	  }
697	
698	  function paneTitle(scope: ScopeId): string {
699	    const data = scopeSnapshot(scope);
700	    const count = data?.skills.length || 0;
701	    const hidden = data?.hiddenLockEntries || 0;
702	    const parts = [`${scope === 'project' ? 'Project' : 'Global'} ${count}`];
703	    if (count > paneBudget()) parts.push(`${cursor()[scope] + 1}/${count}`);
704	    if (hidden) parts.push(`${hidden} hidden`);
705	    return parts.join(' · ');
706	  }
707	
708	  const modalTitle = createMemo(() => {
709	    const active = modal();
710	    if (!active) return '';
711	    if (active.type === 'search') {
712	      return `Install in ${active.scope} scope`;
713	    }
714	    if (active.type === 'fork') return `Fork ${active.skill.folderName}`;
715	    return active.title;
716	  });
717	
718	  const modalContent = () => {
719	    const active = modal();
720	    if (!active) return null;
721	    if (active.type === 'confirm') return <ConfirmView modal={active} />;
722	    if (active.type === 'fork') return <ForkView modal={active} />;
723	    return active.phase === 'query' ? (
724	      <SearchQueryView modal={active} />
725	    ) : (
726	      <SearchResultsView modal={active} projectEnabled={projectEnabled()} />
727	    );
728	  };
729	
730	  return (
731	    <box width="100%" height="100%" flexDirection="column" backgroundColor={COLORS.bg} padding={1}>
732	      <box height={2} flexDirection="row" justifyContent="space-between">
733	        <text>
734	          <span style={{ fg: COLORS.active, bold: true }}>skillsui</span>
735	        </text>
736	        <text fg={COLORS.dim} truncate={true}>
737	          {shortenHome(props.paths.projectRoot)}
738	        </text>
739	      </box>
740	
741	      <box flexGrow={1} flexDirection="row" gap={1}>
742	        <For each={visibleScopes()}>
743	          {(scope) => (
744	            <SkillPane
745	              scope={scope}
746	              title={paneTitle(scope)}
747	              active={activeScope() === scope}
748	              solo={!projectEnabled()}
749	              rows={paneRows(scope)}
750	              empty={scopeSkills(scope).length === 0}
751	              cursorId={currentSkill()?.id ?? null}
752	              selected={(id) => selected().has(id)}
753	              updateState={(id) => updates()[id]}
754	            />
755	          )}
756	        </For>
757	      </box>
758	
759	      <StatusBar
760	        status={status()}
761	        alert={statusTone() === 'alert'}
762	        busy={busy() || loading()}
763	        skill={currentSkill()}
764	        projectEnabled={projectEnabled()}
765	      />
766	
767	      <Show when={modal()}>
768	        <ModalFrame title={modalTitle()} danger={modal()?.type === 'confirm'}>
