349	          props.projectEnabled === false
350	            ? [
351	                ['j/k', 'move'],
352	                ['n/p', 'page'],
353	                ['Enter', 'install'],
354	                ['i', 'global'],
355	                ['PageUp/PageDown', 'preview'],
356	                ['Esc', 'search'],
357	              ]
358	            : [
359	                ['j/k', 'move'],
360	                ['n/p', 'page'],
361	                ['Enter', 'install'],
362	                ['i', 'project'],
363	                ['I', 'global'],
364	                ['PageUp/PageDown', 'preview'],
365	                ['Esc', 'search'],
366	              ]
367	        }
368	      />
369	    </>
370	  );
371	}
