33	  const [cursor, setCursor] = createSignal<Record<ScopeId, number>>({ project: 0, global: 0 });
34	  const [selected, setSelected] = createSignal(new Set<string>());
35	  const [updates, setUpdates] = createSignal<Record<string, UpdateState>>({});
36	  const [status, setStatus] = createSignal('Loading skills');
37	  const [statusTone, setStatusTone] = createSignal<'idle' | 'alert'>('idle');
38	  const [busy, setBusy] = createSignal(false);
39	  const [loading, setLoading] = createSignal(false);
40	
41	  let disposed = false;
42	  let checkGeneration = 0;
43	
44	  const projectEnabled = () => paths.projectEnabled;
45	  const visibleScopes = (): ScopeId[] =>
46	    projectEnabled() ? (['project', 'global'] as ScopeId[]) : (['global'] as ScopeId[]);
47	
48	  function focusScope(scope: ScopeId): void {
49	    if (scope === 'project' && !projectEnabled()) return;
50	    setActiveScope(scope);
51	  }
52	
53	  function announce(message: string, alert = false): void {
54	    setStatus(message);
55	    setStatusTone(alert ? 'alert' : 'idle');
56	  }
57	
58	  const scopeSnapshot = (scope: ScopeId) => snapshot()?.[scope];
59	  const scopeSkills = (scope: ScopeId) => scopeSnapshot(scope)?.skills || [];
60	  const currentSkill = createMemo(() => {
61	    const list = scopeSkills(activeScope());
62	    return list[cursor()[activeScope()]] || null;
63	  });
64	  const selectedSkills = createMemo(() => {
65	    const ids = selected();
66	    return allSkills(snapshot()).filter((skill) => ids.has(skill.id));
67	  });
68	  const isSelected = (id: string) => selected().has(id);
69	
70	  function toggleSelection(id: string): void {
71	    setSelected((previous) => {
72	      const next = new Set(previous);
73	      if (next.has(id)) next.delete(id);
74	      else next.add(id);
75	      return next;
76	    });
77	  }
78	
79	  function moveCursor(delta: number): void {
80	    const scope = activeScope();
81	    const length = scopeSkills(scope).length;
82	    if (length === 0) return;
83	    setCursor((current) => ({
84	      ...current,
85	      [scope]: Math.max(0, Math.min(current[scope] + delta, length - 1)),
86	    }));
87	  }
88	
89	  function clampCursors(data: AppSnapshot): void {
90	    setCursor((previous) => ({
91	      project: Math.max(0, Math.min(previous.project, data.project.skills.length - 1)),
92	      global: Math.max(0, Math.min(previous.global, data.global.skills.length - 1)),
93	    }));
94	  }
95	
96	  async function runBackgroundCheck(data: AppSnapshot): Promise<void> {
97	    const generation = ++checkGeneration;
98	    const tracked = allSkills(data).filter((skill) => skill.tracked);
99	    const initial: Record<string, UpdateState> = {};
100	    for (const skill of tracked) initial[skill.id] = 'checking';
101	    setUpdates(initial);
102	    if (tracked.length === 0) return;
103	
104	    const result = await checkForUpdates(tracked);
105	    if (disposed || generation !== checkGeneration) return;
106	    setUpdates(result.states);
107	    const available = Object.values(result.states).filter((state) => state === 'available').length;
108	    if (available > 0) {
109	      announce(`${available} update${available === 1 ? '' : 's'} available`, true);
110	    } else if (result.errors.length > 0) {
111	      announce('Local skills ready. Some updates could not be checked', true);
112	    }
113	  }
114	
115	  async function refresh(check = true): Promise<void> {
116	    setLoading(true);
117	    try {
118	      const data = await discoverAll(paths);
119	      if (disposed) return;
120	      setSnapshot(data);
121	      clampCursors(data);
122	      const existing = new Set(allSkills(data).map((skill) => skill.id));
123	      setSelected((previous) => new Set([...previous].filter((id) => existing.has(id))));
124	      announce(
125	        projectEnabled()
126	          ? `${data.project.skills.length} project, ${data.global.skills.length} global`
127	          : `${data.global.skills.length} global`
128	      );
129	      if (check) void runBackgroundCheck(data);
130	    } catch (error) {
131	      announce((error as Error).message, true);
132	    } finally {
133	      setLoading(false);
134	    }
135	  }
136	
137	  async function runOperation(
138	    label: string,
139	    action: () => Promise<OperationResult>
140	  ): Promise<void> {
141	    options.onOperationStart?.();
142	    setBusy(true);
143	    announce(label);
144	    try {
145	      const result = await action();
146	      setSelected(new Set<string>());
147	      await refresh(true);
148	      announce(operationStatus(result), result.errors.length > 0);
149	    } catch (error) {
150	      announce((error as Error).message, true);
151	    } finally {
152	      setBusy(false);
153	    }
154	  }
155	
156	  /** The batch an action applies to: the selection, or the cursor when nothing is selected. */
157	  function actionTargets(scope?: ScopeId): SkillRecord[] {
158	    const chosen = selectedSkills().filter((skill) => !scope || skill.scope === scope);
159	    if (chosen.length > 0) return chosen;
160	    const current = currentSkill();
161	    return current && (!scope || current.scope === scope) ? [current] : [];
162	  }
163	
164	  onCleanup(() => {
165	    disposed = true;
166	    checkGeneration++;
167	  });
168	
169	  return {
170	    projectEnabled,
171	    visibleScopes,
172	    activeScope,
173	    focusScope,
174	    snapshot,
175	    scopeSnapshot,
176	    scopeSkills,
177	    cursor,
178	    moveCursor,
179	    currentSkill,
180	    selectedSkills,
181	    isSelected,
182	    toggleSelection,
183	    actionTargets,
184	    updates,
185	    status,
186	    statusTone,
187	    busy,
188	    loading,
189	    setBusy,
190	    announce,
191	    refresh,
192	    runOperation,
193	  };
194	}

