13	/** The slice of a scope's skills that keeps the cursor centred. */
14	export function paneWindow(skills: SkillRecord[], cursor: number, capacity: number): SkillRecord[] {
15	  const start = Math.max(0, Math.min(cursor - Math.floor(capacity / 2), skills.length - capacity));
16	  return skills.slice(start, start + capacity);
17	}
