19	export function paneTitle(
20	  scope: ScopeId,
21	  snapshot: ScopeSnapshot | undefined,
22	  cursor: number,
23	  capacity: number
24	): string {
25	  const count = snapshot?.skills.length || 0;
26	  const hidden = snapshot?.hiddenLockEntries || 0;
27	  const parts = [`${scope === 'project' ? 'Project' : 'Global'} ${count}`];
28	  if (count > capacity) parts.push(`${cursor + 1}/${count}`);
29	  if (hidden) parts.push(`${hidden} hidden`);
30	  return parts.join(' · ');
