41	  const marker = () =>
42	    props.updateState === 'available'
43	      ? '↑ update'
44	      : props.updateState === 'checking'
45	        ? 'checking…'
46	        : props.updateState === 'unavailable'
47	          ? 'unchecked'
48	          : '';
49	  const badge = () => (props.skill.tracked ? 'tracked' : 'local');
50	  const right = () => (marker() ? `${marker()} ${badge()}` : badge());
51	  const name = () => fit(props.skill.folderName, props.width - 7 - right().length);
52	
53	  return (
54	    <box
55	      height={1}
56	      width="100%"
57	      flexDirection="row"
58	      backgroundColor={props.focused ? COLORS.cursor : props.checked ? COLORS.selected : undefined}
59	    >
60	      <text flexGrow={1} truncate={true}>
61	        <span style={{ fg: props.focused ? COLORS.active : COLORS.dim }}>
62	          {props.focused ? '❯ ' : '  '}
63	        </span>
64	        <span style={{ fg: props.checked ? COLORS.accent : COLORS.dim }}>
65	          {props.checked ? '[x] ' : '[ ] '}
66	        </span>
67	        {props.focused ? (
68	          <b style={{ fg: nameColor() }}>{name()}</b>
69	        ) : (
70	          <span style={{ fg: nameColor() }}>{name()}</span>
71	        )}
72	      </text>
73	      <text flexShrink={0}>
74	        {props.updateState === 'available' ? (
