100	
101	  return (
102	    <box
103	      width={props.solo ? '100%' : '50%'}
104	      height="100%"
105	      flexDirection="column"
106	      border={true}
107	      borderStyle="rounded"
108	      borderColor={props.active ? COLORS.active : COLORS.border}
109	      backgroundColor={props.active ? COLORS.panelActive : COLORS.panel}
110	      title={props.title}
111	      titleColor={props.active ? COLORS.active : COLORS.dim}
112	      paddingX={1}
113	      overflow="hidden"
114	    >
115	      <Show
116	        when={!props.empty}
117	        fallback={
118	          <box flexGrow={1} flexDirection="column" justifyContent="center" alignItems="center">
119	            <text fg={COLORS.dim}>No skills in this scope</text>
120	            <text>
121	              <span style={{ fg: COLORS.text, bold: true }}>
122	                {props.scope === 'project' || props.solo ? 'i' : 'I'}
123	              </span>
124	              <span style={{ fg: COLORS.dim }}>{' install from skills.sh'}</span>
125	            </text>
126	          </box>
127	        }
128	      >
129	        <For each={props.rows}>
130	          {(skill) => (
131	            <SkillRow
